\set ON_ERROR_STOP on
create temporary table finalized_upload as select * from public.finalize_video_source_upload('40000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001',:'CLAIM_TOKEN','private-bucket',:'FINAL_KEY','image/png',1000,repeat('a',64));
do $$ declare r record;begin select * into r from public.finalize_video_source_upload('40000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001',gen_random_uuid(),'wrong-bucket','wrong-key','image/png',1000,repeat('b',64));assert r.generation_id=(select generation_id from finalized_upload) and r.generation_asset_id=(select generation_asset_id from finalized_upload);assert (select metadata->>'policy_version'='1' and mode='video_source_import' and job_type='image' and image_url is null from public.generations where id=r.generation_id);end$$;
do $$ declare payload jsonb;p uuid;j public.compute_jobs;a uuid;asset uuid:=(select generation_asset_id from finalized_upload);begin payload:=jsonb_build_object('mode','image_to_video','prompt','','negative_prompt','','body_type','none','identity_id',null,'source_generation_asset_id',asset,'requested_duration_seconds',10,'motion_strength',.65);select project_id into p from public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001',null,asset,'imported-source',repeat('b',64),payload,'standard');select * into j from public.compute_jobs where id=(select video_job_id from public.video_projects where id=p);update public.compute_jobs set state='claimed',attempt_count=1,lease_token='50000000-0000-4000-8000-000000000001',lease_expires_at=now()+interval '5 minutes' where id=j.id;insert into public.compute_job_attempts(job_id,ordinal,lease_token,worker_ref,lease_expires_at)values(j.id,1,'50000000-0000-4000-8000-000000000001','test',now()+interval '5 minutes')returning id into a;assert public.video_compute_manifest(j.id,a,'50000000-0000-4000-8000-000000000001')=j.request_payload;update public.compute_jobs set request_payload=jsonb_set(request_payload,'{prompt}',to_jsonb('tampered'::text));begin perform public.video_compute_manifest(j.id,a,'50000000-0000-4000-8000-000000000001');raise exception 'tampered request accepted';exception when others then assert sqlerrm like '%VIDEO_REQUEST_AUTHORITY_MISMATCH%';end;update public.compute_jobs set request_payload=j.request_payload,state='recovering',lease_token=null,lease_expires_at=null where id=j.id;update public.compute_job_attempts set recovery_token='60000000-0000-4000-8000-000000000001',recovery_lease_token='60000000-0000-4000-8000-000000000002',recovery_worker_ref='recovery-test',recovery_heartbeat_at=now(),recovery_lease_expires_at=now()+interval '5 minutes' where id=a;assert public.recovered_video_compute_manifest(j.id,a,'60000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000002')=j.request_payload;end$$;
do $$ begin begin perform public.claim_video_source_upload_finalization('40000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002',gen_random_uuid());raise exception 'foreign accepted';exception when others then assert sqlerrm like '%NOT_FOUND%';end;begin perform public.create_video_source_upload('40000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','private-bucket','creator-video-source-staging/10000000-0000-4000-8000-000000000001/40000000-0000-4000-8000-000000000002.jpg','image/png',10,now()+interval '30 minutes');raise exception 'MIME mismatch accepted';exception when others then assert sqlerrm like '%INVALID%';end;end$$;
